package main

import (
	"fmt"
	"strings"
	"strconv"
)

type YAMLNode map[string]interface{}

func ParseYAML(input string) YAMLNode {
	lines := strings.Split(input, "\n")
	return parseYAMLLines(lines)
}

func parseYAMLLines(lines []string) YAMLNode {
	root := YAMLNode{}
	currentNode := root
	previousIndent := -1

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}

		indent := getIndent(line)
		value := strings.TrimSpace(line[indent:])
		if indent > previousIndent {
			// We are moving deeper into the YAML structure
			parentKey := currentNode
			for i := previousIndent + 1; i <= indent; i++ {
				parentKey = parentKey[fmt.Sprintf("%d", i)]
			}
			newNode := YAMLNode{}
			parentKey[parentKey.Len()] = newNode
			currentNode = newNode
		} else if indent < previousIndent {
			// We are moving up in the YAML structure
			for indent < previousIndent {
				parentKey := currentNode
				parentKey = parentKey[fmt.Sprintf("%d", previousIndent)]
				currentNode = parentKey
				previousIndent--
			}
		}

		// Parse the value
		parsedValue := parseSimpleValue(value)
		currentNode[value] = parsedValue

		previousIndent = indent
	}

	return root
}

func getIndent(s string) int {
	for i, r := range s {
		if r != ' ' {
			return i
		}
	}
	return len(s)
}

func parseSimpleValue(value string) interface{} {
	if strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\"") {
		return strings.Trim(value, "\"")
	}
	if strings.HasPrefix(value, "'") && strings.HasSuffix(value, "'") {
		return strings.Trim(value, "'")
	}
	if strings.HasPrefix(value, "[") && strings.HasSuffix(value, "]") {
		return parseSimpleArray(strings.Trim(value, "[]"))
	}
	if strings.HasPrefix(value, "{") && strings.HasSuffix(value, "}") {
		return parseSimpleMap(strings.Trim(value, "{}"))
	}
	if value == "true" {
		return true
	}
	if value == "false" {
		return false
	}
	if value == "null" {
		return nil
	}
	if intValue, err := strconv.Atoi(value); err == nil {
		return intValue
	}
	if floatValue, err := strconv.ParseFloat(value, 64); err == nil {
		return floatValue
	}
	return value
}

func parseSimpleArray(value string) []interface{} {
	items := strings.Split(value, ",")
	result := make([]interface{}, len(items))
	for i, item := range items {
		result[i] = parseSimpleValue(strings.TrimSpace(item))
	}
	return result
}

func parseSimpleMap(value string) YAMLNode {
	parts := strings.Split(value, ",")
	result := YAMLNode{}
	for _, part := range parts {
		keyValue := strings.SplitN(strings.TrimSpace(part), ":", 2)
		if len(keyValue) == 2 {
			key := strings.TrimSpace(keyValue[0])
			value := parseSimpleValue(strings.TrimSpace(keyValue[1]))
			result[key] = value
		}
	}
	return result
}

